+// Who may do what: API keys, roles and the audit trail (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+/** The roles, from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Writes a cook may do; every other write, and GET /audit, is for managers.
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The key record for an `Authorization: Bearer <key>` header value, or throws unauthorized. */
+export function authenticate(store, header) {
+  const m = /^Bearer\s+(\S+)$/i.exec(typeof header === "string" ? header.trim() : "");
+  const known = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!known) throw new AppError("unauthorized");
+  return known;
+}
+
+/** Throws forbidden unless a key with `role` may make this request. */
+export function authorize(role, method, path) {
+  if (method === "GET" && path !== "/audit") return;
+  if (role === "manager") return;
+  if (role === "cook" && COOK_WRITES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
+
+/** True when a request with this method changes data and so is audited. */
+export const isWrite = (method) => method !== "GET" && method !== "HEAD";
+
+/** Appends an audit entry (time, key name, method, path, status). */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit.push({ at, key: keyName, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
